/* Token Radar. Palette: two validated inks (#2a78d6 blue for the model's implied value,
   #eb6834 orange for what already trades), neutral ink for text, one hairline. */
:root {
  --surface: #fcfcfb;
  --plane: #f4f4f1;
  --ink: #0b0b0b;
  --ink-2: #52514e;
  --muted: #898781;
  --line: #e1e0d9;
  --blue: #2a78d6;
  --blue-soft: #e8f0fc;
  --orange: #eb6834;
  --orange-soft: #fdeee7;
  --good: #006300;
  --bad: #b3362a;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 14px;
  --s1: 4px;
  --s2: 8px;
  --s3: 12px;
  --s4: 16px;
  --s5: 24px;
  --s6: 32px;
  --s7: 44px;
  --font: system-ui, -apple-system, "Segoe UI", sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  color-scheme: light;
}
@media (prefers-color-scheme: dark) {
